TLValue emit_program(TLValue stmts) {
  TLValue header = tl_str("// ============================================================================\n");
  (header = concat(header, tl_str("// Generated by TypeLang Self-Hosted C11 / C99 Compiler\n")));
  (header = concat(header, tl_str("// ============================================================================\n\n")));
  (header = concat(header, tl_str("#include \"tl_runtime.h\"\n\n")));
  TLValue prototypes = tl_str("// --- Function Prototypes ---\n");
  TLValue functions = tl_str("// --- Function Implementations ---\n");
  TLValue mainBody = tl_str("");
  TLValue i = tl_num(0);
  TLValue count = Array_len(stmts);
  while (tl_is_truthy(tl_lt(i, count))) {
    TLValue st = tl_get_index(stmts, i);
    if (tl_is_truthy(tl_eq(tl_get_index(st, tl_num(0)), tl_num(27)))) {
      TLValue fnName = tl_get_index(st, tl_num(1));
      TLValue params = tl_get_index(st, tl_num(2));
      TLValue body = tl_get_index(st, tl_num(3));
      TLValue safeFnName = sanitize_c_ident(fnName);
      TLValue paramListStr = tl_str("");
      TLValue pCount = Array_len(params);
      TLValue pIdx = tl_num(0);
      while (tl_is_truthy(tl_lt(pIdx, pCount))) {
        if (tl_is_truthy(tl_gt(pIdx, tl_num(0)))) {
          (paramListStr = concat(paramListStr, tl_str(", ")));
        }
        (paramListStr = concat(paramListStr, concat(tl_str("TLValue "), sanitize_c_ident(tl_get_index(params, pIdx)))));
        (pIdx = tl_add(pIdx, tl_num(1)));
      }
      if (tl_is_truthy(tl_eq(pCount, tl_num(0)))) {
        (paramListStr = tl_str("void"));
      }
      (prototypes = concat(prototypes, concat(concat(tl_str("TLValue "), safeFnName), concat(tl_str("("), concat(paramListStr, tl_str(");\n"))))));
      TLValue fnImpl = concat(concat(tl_str("TLValue "), safeFnName), concat(tl_str("("), concat(paramListStr, tl_str(") {\n"))));
      TLValue bIdx = tl_num(0);
      TLValue bCount = Array_len(body);
      while (tl_is_truthy(tl_lt(bIdx, bCount))) {
        (fnImpl = concat(fnImpl, emit_statement(tl_get_index(body, bIdx), tl_str("  "))));
        (bIdx = tl_add(bIdx, tl_num(1)));
      }
      (fnImpl = concat(fnImpl, tl_str("  return tl_null();\n}\n\n")));
      (functions = concat(functions, fnImpl));
    } else {
      (mainBody = concat(mainBody, emit_statement(st, tl_str("  "))));
    }
    (i = tl_add(i, tl_num(1)));
  }
  TLValue mainFn = tl_str("// --- Main Entry Point ---\n");
  (mainFn = concat(mainFn, tl_str("int main(int argc, char** argv) {\n")));
  (mainFn = concat(mainFn, tl_str("  _tl_argc = argc; _tl_argv = argv;\n\n")));
  (mainFn = concat(mainFn, mainBody));
  (mainFn = concat(mainFn, tl_str("  return 0;\n")));
  (mainFn = concat(mainFn, tl_str("}\n")));
  return concat(concat(concat(header, prototypes), concat(tl_str("\n"), functions)), concat(tl_str("\n"), mainFn));
}

TLValue compile_source(TLValue sourceCode) {
  TLValue tokens = tokenize(sourceCode);
  println(concat(tl_str("Scanned Token Count: "), to_string(Array_len(tokens))));
  TLValue parseResult = parse(tokens);
  println(concat(tl_str("Parsed Statement Count: "), to_string(Array_len(tl_get_field(parseResult, "stmts")))));
  if (tl_is_truthy(tl_gt(Array_len(tl_get_field(parseResult, "errors")), tl_num(0)))) {
    println(tl_str("❌ Parsing Errors Encountered:"));
    TLValue errIdx = tl_num(0);
    TLValue errCount = Array_len(tl_get_field(parseResult, "errors"));
    while (tl_is_truthy(tl_lt(errIdx, errCount))) {
      println(concat(tl_str("  - "), tl_get_index(tl_get_field(parseResult, "errors"), errIdx)));
      (errIdx = tl_add(errIdx, tl_num(1)));
    }
    return tl_str("");
  }
  TLValue checkResult = check_semantics(tl_get_field(parseResult, "stmts"));
  if (tl_is_truthy(tl_not(tl_get_field(checkResult, "isValid")))) {
    println(tl_str("❌ Semantic Errors Encountered:"));
    TLValue errIdx = tl_num(0);
    TLValue errCount = Array_len(tl_get_field(checkResult, "errors"));
    while (tl_is_truthy(tl_lt(errIdx, errCount))) {
      println(concat(tl_str("  - "), tl_get_index(tl_get_field(checkResult, "errors"), errIdx)));
      (errIdx = tl_add(errIdx, tl_num(1)));
    }
    return tl_str("");
  }
  TLValue cSource = emit_program(tl_get_field(parseResult, "stmts"));
  return cSource;
}

TLValue run_compiler_cli(void) {
  TLValue cliInput = get_cli_arg(tl_num(1));
  return (tl_is_truthy(tl_ne(cliInput, tl_str(""))) ? ({
    TLValue sourceText = read_file(cliInput);
    (tl_is_truthy(tl_ne(sourceText, tl_str(""))) ? ({
      TLValue emittedC = compile_source(sourceText);
      TLValue cliOutput = get_cli_arg(tl_num(2));
      (tl_is_truthy(tl_ne(cliOutput, tl_str(""))) ? ({
        write_file(cliOutput, emittedC);
        println(concat(tl_str("✓ Successfully compiled to "), cliOutput));
        tl_null();
}) : ({
        println(emittedC);
        tl_null();
}));
}) : ({
      println(concat(tl_str("❌ Error reading input file: "), cliInput));
      tl_null();
}));
}) : ({
    println(tl_str("🚀 TypeLang Self-Hosted C11 / C99 Native Compiler Initialized"));
    TLValue sampleProgram = tl_str("println(\"Hello from TypeLang Compiled C11!\");\nlet x = 10.0 + 32.0;\nprintln(concat(\"Computed value: \", to_string(x)));\n");
    TLValue compiledOutput = compile_source(sampleProgram);
    println(tl_str("✓ Emitted C11 Code Preview:"));
    println(compiledOutput);
    tl_null();
}));
}

// Entry Point
int main(int argc, char** argv) {
  // Initialize runtime environment
  (void)argc; (void)argv;
  _tl_argc = argc; _tl_argv = argv;
run_compiler_cli();
  return 0;
}